import 'package:flutter/material.dart';
class BackgroundGrid extends StatelessWidget {const BackgroundGrid({super.key});@override Widget build(BuildContext context)=>RepaintBoundary(child:CustomPaint(painter:const _GridPainter(),size:Size.infinite));}
class _GridPainter extends CustomPainter {const _GridPainter();@override void paint(Canvas canvas,Size size){final p=Paint()..color=Colors.cyanAccent.withValues(alpha:.10)..strokeWidth=1;const step=40.0;for(double x=0;x<size.width;x+=step){canvas.drawLine(Offset(x,0),Offset(x,size.height),p);}for(double y=0;y<size.height;y+=step){canvas.drawLine(Offset(0,y),Offset(size.width,y),p);}}@override bool shouldRepaint(covariant _GridPainter oldDelegate)=>false;}
